 const choice=(title,why,question,options,answer,equations)=>({title,why,question,options,answer,solution:equations.join('; '),hint:{reminder:why,inputs:question},worked:[{text:why,equations}]});
 const add=(id,typeName,prompt,steps)=>D.problems.push({id:'calc-'+id,group:'integrals',title:'Integration · calculus practice',typeName,workspace:'calcPractice',description:'Understand the integration method, perform each algebraic step, and check by differentiation.',prompt,steps});
 add('notation','Read integral notation','Interpret <strong>∫₁³ (2x + 1) dx</strong> before calculating.',[choice('Identify the integrand','The integrand is the function being accumulated. dx names the integration variable.','What is the integrand?',['2x + 1','dx','1 and 3'],0,['Integrand: f(x) = 2x + 1']),choice('Read the bounds','The lower bound is the starting x value; the upper bound is the ending x value.','Which describes these bounds?',['x runs from 1 to 3','Function values run from 1 to 3','There are exactly 3 rectangles'],0,['a = 1; b = 3']),numeric('Evaluate the accumulation','An antiderivative is x² + x. Evaluate upper minus lower.',['Integral value'],[10],['F(x) = x² + x','F(3) − F(1) = (9 + 3) − (1 + 1) = 10'])]);
 add('constant','Why +C matters','Find the antiderivative of <strong>6x</strong>.',[numeric('Reverse the derivative','Seek F(x) = a x^p + C. Differentiating it must return 6x.',['a','p'],[3,2],['d(a x²)/dx = 2a x','2a = 6; a = 3; p = 2']),choice('Include the family','Every constant differentiates to zero, so the indefinite integral describes a family.','Which is the complete indefinite integral?',['3x² + C','3x² only','6x² + C'],0,['∫ 6x dx = 3x² + C']),numeric('Use an initial condition','If F(1) = 8, substitute x = 1 to determine the constant.',['C'],[5],['8 = 3(1)² + C','C = 5'])]);
 for(const [id,c,n] of [['power',8,3],['root',3,.5],['negative',6,-3]]){
  add(id,id==='root'?'Integrate a square root':id==='negative'?'Integrate a negative power':'Power rule step by step',`Find <strong>∫ ${c}x^(${n}) dx</strong>, written as <strong>a x^p + C</strong>.`,[numeric('Increase the exponent','For x^n, the antiderivative exponent is n + 1. This rule excludes n = −1.',['p'],[n+1],[`p = ${n} + 1 = ${n+1}`]),numeric('Divide by the new exponent','Divide the original coefficient by n + 1, not by n.',['a'],[c/(n+1)],[`a = ${c}/(${n+1}) = ${c/(n+1)}`,`F(x) = ${c/(n+1)} x^(${n+1}) + C`]),numeric('Differentiate to check','The derivative coefficient is a p and the exponent is p − 1. It must recover the given integrand.',['Derivative coefficient','Derivative exponent'],[c,n],[`F′(x) = (${c/(n+1)})(${n+1})x^(${n}) = ${c}x^(${n})`])]);
 }
 add('linearity','Integrate a polynomial term by term','Find <strong>∫ (6x² − 4x + 5) dx = ax³ + bx² + cx + C</strong>.',[numeric('Integrate each term','Integration distributes over sums and differences. Keep each coefficient’s sign.',['a','b','c'],[2,-2,5],['∫ 6x² dx = 2x³','∫ −4x dx = −2x²','∫ 5 dx = 5x']),choice('Use one arbitrary constant','Individual integration constants can be combined into one arbitrary constant.','Which answer is complete?',['2x³ − 2x² + 5x + C','2x³ + 2x² + 5x','12x³ − 4x² + 5x + C'],0,['F′(x) = 6x² − 4x + 5'])]);
 add('bounds','Evaluate a definite integral','Evaluate <strong>∫₁³ (2x + 4) dx</strong>.',[numeric('Find an antiderivative','Integrate each term; C will cancel between the bounds. For F(x) = ax² + bx, find a and b.',['a','b'],[1,4],['F(x) = x² + 4x']),numeric('Evaluate both endpoints','Substitute each bound into the entire antiderivative.',['F(3)','F(1)'],[21,5],['F(3) = 3² + 4(3) = 21','F(1) = 1² + 4(1) = 5']),numeric('Subtract lower from upper','The Fundamental Theorem of Calculus uses F(b) − F(a), not f(b) − f(a).',['Integral value'],[16],['∫₁³ (2x + 4) dx = 21 − 5 = 16'])]);
 add('signed','Signed integral versus geometric area','For <strong>f(x) = x</strong> on <strong>[−1,1]</strong>, compare accumulation with total geometric area.',[numeric('Evaluate the signed integral','The below-axis part contributes negatively and cancels the above-axis part.',['Signed integral'],[0],['F(x) = x²/2','F(1) − F(−1) = 1/2 − 1/2 = 0']),numeric('Add nonnegative areas','Total geometric area is ∫ |x| dx. Split where the function crosses zero.',['Total area'],[1],['Area = 1/2 + 1/2 = 1']),choice('Interpret cancellation','A zero integral does not require the original function to be identically zero.','What does zero signed accumulation mean here?',['Equal positive and negative contributions','No area on either side','The function has no antiderivative'],0,['∫₋₁¹ x dx = 0, but ∫₋₁¹ |x| dx = 1'])]);
 add('reverse','Reversed bounds','Evaluate <strong>∫₃¹ 2x dx</strong>.',[numeric('Use the stated upper and lower bounds','The first bound is a = 3; the second is b = 1. Do not silently reorder them.',['F(b)','F(a)'],[1,9],['F(x) = x²','F(1) = 1; F(3) = 9']),numeric('Keep the orientation','Reversing integration limits negates the integral.',['Integral value'],[-8],['F(1) − F(3) = 1 − 9 = −8'])]);
 add('substitution','u-substitution with an exact derivative','Find <strong>∫ 2x(x² + 1)³ dx</strong>, written as <strong>a(x² + 1)^p + C</strong>.',[choice('Choose the inner expression','The derivative of x² + 1 is the factor 2x already present.','Which substitution matches the chain rule?',['u = x² + 1, du = 2x dx','u = 2x, du = x² dx','u = x³, du = 2x dx'],0,['∫ 2x(x² + 1)³ dx = ∫ u³ du']),numeric('Integrate in u','Apply the power rule after replacing both the inner expression and its differential.',['a','p'],[.25,4],['∫ u³ du = u⁴/4 + C','F(x) = (x² + 1)⁴/4 + C']),choice('Check the chain factor','Differentiating the answer must include the derivative of x² + 1.','Which derivative is correct?',['(1/4)·4(x²+1)³·2x','(x²+1)³ only','4(x²+1)³'],0,['F′(x) = 2x(x² + 1)³'])]);
