 add('log','The n = −1 exception','Evaluate <strong>∫₁⁴ (3/x) dx</strong>.',[choice('Choose the logarithm rule','The power rule would divide by zero for n = −1. On an interval excluding zero, ∫ dx/x = ln|x| + C.','Which antiderivative works?',['3 ln|x| + C','3x⁰/0 + C','3x⁻² + C'],0,['d(3 ln|x|)/dx = 3/x, x ≠ 0']),numeric('Evaluate on the positive interval','Natural logarithm means log base e. The interval [1,4] excludes the singularity x = 0.',['Integral value'],[3*Math.log(4)],['3 ln4 − 3 ln1 = 3 ln4'])]);
 add('exponential','Exponential integral and chain factor','Find <strong>∫ 5e^(2x) dx = a e^(2x) + C</strong>.',[numeric('Compensate for the inner derivative','Differentiating e^(2x) produces an extra factor of 2. Divide the coefficient by 2.',['a'],[2.5],['a = 5/2 = 2.5','F(x) = (5/2)e^(2x) + C']),numeric('Check by differentiation','Multiply by the inner derivative to recover the original coefficient.',['Derivative coefficient'],[5],['F′(x) = (5/2)·2e^(2x) = 5e^(2x)'])]);
 add('trig','Trigonometric integral in radians','Evaluate <strong>∫₀^(π/2) sin x dx</strong>.',[choice('Reverse the cosine derivative','d(cos x)/dx = −sin x, so the antiderivative of sin x is −cos x. Standard calculus trig rules use radians.','Which antiderivative is correct?',['−cos x + C','cos x + C','sin x + C'],0,['F(x) = −cos x']),numeric('Evaluate both endpoints','Use radian mode when entering π/2 in a calculator.',['Integral value'],[1],['[−cos x]₀^(π/2) = −cos(π/2) − (−cos0) = 0 + 1 = 1'])]);
 add('parts','Integration by parts','Find <strong>∫ x e^x dx = (ax + b)e^x + C</strong>.',[choice('Select u and dv','Differentiate the polynomial and integrate the exponential to simplify the remaining integral.','Which choice is useful?',['u = x; dv = e^x dx','u = e^x; dv = x dx','u = x e^x; dv = 0'],0,['du = dx; v = e^x','∫ u dv = uv − ∫ v du']),numeric('Subtract the remaining integral','The first term is x e^x. The remaining integral is ∫ e^x dx.',['a','b'],[1,-1],['∫ x e^x dx = x e^x − e^x + C = (x − 1)e^x + C']),choice('Check with the product rule','Differentiate both factors of (x − 1)e^x.','Which check recovers the integrand?',['e^x + (x − 1)e^x = x e^x','(x − 1)e^x only','e^x − (x − 1)e^x'],0,['F′(x) = x e^x'])]);
 add('piecewise','Split a piecewise load integral','A beam has <strong>w = 100 N/m on [0,2] m</strong> and <strong>w = 200 N/m on (2,3] m</strong>, both downward.',[numeric('Integrate each interval','Use each function only over the interval where it applies. Report downward magnitudes.',['First force (N)','Second force (N)'],[200,200],['F1 = ∫₀² 100 dx = 200 N','F2 = ∫₂³ 200 dx = 200 N']),numeric('Compute first moment using global x','The second interval still uses x measured from the original O, not a new origin at 2 m.',['Q1 (N·m)','Q2 (N·m)'],[200,500],['Q1 = [50x²]₀² = 200 N·m','Q2 = [100x²]₂³ = 100(9 − 4) = 500 N·m']),numeric('Combine force and location','Divide the combined first moment by the combined force.',['Force (N)','x bar (m)'],[400,1.75],['FR = 200 + 200 = 400 N','x bar = (200 + 500)/400 = 1.75 m'])]);
 add('load','Quadratic loading from calculus','A downward line load is <strong>w(x) = 12x² N/m</strong> on <strong>[0,3] m</strong>; the coefficient has units N/m³.',[numeric('Integrate force intensity','dF = w dx. Add one to the power and divide by the new power.',['Force (N)'],[108],['FR = ∫₀³ 12x² dx = [4x³]₀³','FR = 4(27) = 108 N']),numeric('Integrate the first moment','dQ = x dF = x w(x) dx. Multiplication by x increases the integrand power by one.',['First moment (N·m)'],[243],['Q = ∫₀³ 12x³ dx = [3x⁴]₀³','Q = 3(81) = 243 N·m']),numeric('Find the equivalent force location','Force and first moment must use the same origin, limits, and sign convention.',['x bar (m)'],[2.25],['x bar = Q/FR = 243/108 = 2.25 m'])]);
 add('riemann','Build a Riemann sum','Approximate <strong>∫₀² x² dx</strong> using <strong>two right-endpoint rectangles</strong>.',[numeric('Divide the interval','Equal-width rectangles have Δx = (b − a)/n.',['Delta x'],[1],['Δx = (2 − 0)/2 = 1']),numeric('Sample the right endpoints','The right endpoints of [0,1] and [1,2] are 1 and 2. Heights are function values, not x values.',['First height','Second height'],[1,4],['f(1) = 1; f(2) = 4']),numeric('Add height times width','This finite sum approximates the integral. For this increasing curve the right-endpoint sum overestimates.',['Approximate integral'],[5],['R2 = (1 + 4)(1) = 5','Exact integral = [x³/3]₀² = 8/3 ≈ 2.66667'])]);
 const functions={square:{f:x=>x*x,F:x=>x**3/3,label:'x²'},linear:{f:x=>x,F:x=>x*x/2,label:'x'},signed:{f:x=>2*x-2,F:x=>x*x-2*x,label:'2x − 2'}};
 function riemann(name,n,method){const fn=functions[name];if(!fn||!Number.isInteger(n)||n<1||n>100||!['left','right','midpoint'].includes(method))throw new Error('Invalid rectangle settings');const dx=2/n,offset={left:0,right:1,midpoint:.5}[method],rectangles=Array.from({length:n},(_,i)=>({left:i*dx,right:(i+1)*dx,sample:(i+offset)*dx,height:fn.f((i+offset)*dx)}));return {dx,rectangles,approx:rectangles.reduce((s,r)=>s+r.height*dx,0),exact:fn.F(2)-fn.F(0)};}
